// MaxLineBytes 是单行原始输入字节数上限（64 MiB），不含行分隔符。
// 内容恰好达到上限仍正常处理；只有严格超过上限的行才因大小失败。
const MaxLineBytes = 64 * 1024 * 1024

// runIngest 逐行处理标准输入，逐行输出 JSON 结果。返回进程退出码。
func runIngest(in io.Reader, out io.Writer) int {
	store := darksafe.NewMetricStore()
	reader := newLineReader(in)
	enc := json.NewEncoder(out)
	enc.SetEscapeHTML(false)

	emit := func(v any) bool {
		if err := enc.Encode(v); err != nil {
			fmt.Fprintln(os.Stderr, "ingest: write error:", err)
			return false
		}
		return true
	}

	exitCode := 0
	lineNo := 0
	for {
		line, tooLong, err := reader.Next()
		if err == io.EOF {
			return exitCode
		}
		if err != nil {
			// 输入读取真正发生故障：按现有方式报告并立即终止。
			fmt.Fprintln(os.Stderr, "ingest: read error:", err)
			return 1
		}
		lineNo++
		if tooLong {
			// 整条超长行（从行首到下一个行分隔符）都属于这一条失败输入：
			// 不解析、不写入任何点、不执行任何查询，只输出一次行错误。
			le := darksafe.NewLineSizeError(MaxLineBytes)
			le.Line = lineNo
			if !emit(le) {
				return 1
			}
			exitCode = 1
			continue
		}
		if len(strings.TrimSpace(string(line))) == 0 {
			continue // 空白行不产生结果，但已计入行号
		}
		result, lineErr := store.ProcessLine(string(line))
		if lineErr != nil {
			lineErr.Line = lineNo
			if !emit(lineErr) {
				return 1
			}
			exitCode = 1
			continue
		}
		if !emit(result) {
			return 1
		}
	}
}

// lineReader 按行从底层 reader 读取，并对单行原始字节数施加上限。
// 它沿用 bufio.Scanner 的换行识别方式：'\n' 为行分隔符，行尾紧跟的
// 单个 '\r' 一并去掉，分隔符不计入行大小。与 Scanner 不同的是：
// 超过上限的行作为一条完整输入被跳过（读取并丢弃直到下一个 '\n'，
// 含末尾无换行直接结束的情况），之后的行仍可继续读取。
type lineReader struct {
	r   io.Reader
	buf []byte
}

func newLineReader(r io.Reader) *lineReader {
	return &lineReader{r: r, buf: make([]byte, 0, 64*1024)}
}

// Next 返回下一行（不含行分隔符）。tooLong 为 true 时该行严格超过
// MaxLineBytes，line 为已读到的前缀（仅用于调用方计数，内容必须整体丢弃）；
// 此时本次调用已把该行剩余部分排干到下一个行分隔符。输入正常结束且没有
// 更多字节时返回 io.EOF；结尾恰好是一个分隔符不会产生额外的空行。
func (lr *lineReader) Next() (line []byte, tooLong bool, err error) {
	lr.buf = lr.buf[:0]
	for {
		if i := bytes.IndexByte(lr.buf, '\n'); i >= 0 {
			line = lr.lineWithoutCR(lr.buf[:i])
			lr.buf = lr.buf[i+1:]
			return line, false, nil
		}
		if len(lr.buf) > MaxLineBytes {
			// 当前行已超限且尚未遇到分隔符：排干该行剩余部分，
			// 让下一次 Next 从下一行的行首开始。
			rest, err := lr.drainLine()
			if err != nil {
				// 含 io.EOF：超长行在输入末尾直接结束也算一条失败行。
				if err != io.EOF {
					return nil, false, err
				}
			}
			lr.buf = rest
			return lr.buf, true, nil
		}
		if len(lr.buf) == cap(lr.buf) {
			lr.grow()
		}
		n, rerr := lr.r.Read(lr.buf[len(lr.buf):cap(lr.buf)])
		lr.buf = lr.buf[:len(lr.buf)+n]
		if rerr != nil && rerr != io.EOF {
			return nil, false, rerr
		}
		if rerr == io.EOF {
			if len(lr.buf) == 0 {
				return nil, false, io.EOF
			}
			// 末尾无换行：剩余内容作为最后一行。
			line = lr.lineWithoutCR(lr.buf)
			lr.buf = lr.buf[:0]
			tooLong = len(line) > MaxLineBytes
			return line, tooLong, nil
		}
	}
}

// drainLine 读取并丢弃直到下一个 '\n'（含）为止的字节，返回 '\n'
// 之后已读到的字节（属于下一行）。'\n' 位于已缓冲内容中时不产生读取。
func (lr *lineReader) drainLine() (rest []byte, err error) {
	if i := bytes.IndexByte(lr.buf, '\n'); i >= 0 {
		return append([]byte(nil), lr.buf[i+1:]...), nil
	}
	tmp := make([]byte, 32*1024)
	for {
		n, rerr := lr.r.Read(tmp)
		if i := bytes.IndexByte(tmp[:n], '\n'); i >= 0 {
			return append([]byte(nil), tmp[i+1:n]...), nil
		}
		if rerr != nil {
			return nil, rerr
		}
	}
}

