// grow 扩大行缓冲；正常行不会超过 MaxLineBytes，上限以内的扩容失败即视为
// 系统资源不足，交给读取错误路径处理。
func (lr *lineReader) grow() {
	size := cap(lr.buf) * 2
	if size < 64*1024 {
		size = 64 * 1024
