		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if tooLong {
			t.Fatalf("short fragmented input must not be too long")
		}
		got = append(got, line)
	}
	if len(got) != len(want) {
		t.Fatalf("got %q, want %q", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("line %d = %q, want %q (got all %q)", i+1, got[i], want[i], got)
		}
	}
}

