		"   ",                                    // 行 2：空白，只占行号
		oversizedLine(limit + 1),                 // 行 3：超长
		oversizedLine(limit + 10),                // 行 4：超长（CRLF 结尾）
		`[{"name":"m","timestamp":1,"value":7}]`, // 行 5：正常写入
