// chunkReader 每次最多返回 n 个字节，模拟管道等会切碎输入的来源；
// 还会随机插入 (0, nil) 之外的合法短读（这里不插入 0,nil，仅固定小块）。
type chunkReader struct {
	data []byte
	n    int
}

func (c *chunkReader) Read(p []byte) (int, error) {
	if len(c.data) == 0 {
		return 0, io.EOF
	}
	n := c.n
	if n > len(p) {
		n = len(p)
	}
	if n > len(c.data) {
		n = len(c.data)
	}
	copy(p, c.data[:n])
	c.data = c.data[n:]
	return n, nil
}

func TestLineReaderFragmentedReads(t *testing.T) {
	// '\r\n' 与各分隔符故意落在读取块边界两侧，最后一行无尾换行。
	input := "ab\r\ncd\nef\r\ng"
	r := newLineReader(&chunkReader{data: []byte(input), n: 3})
	want := []string{"ab", "cd", "ef", "", "g"}
	var got []string
	for {
		line, tooLong, err := r.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if tooLong {
			t.Fatalf("short fragmented input must not be too long")
		}
		got = append(got, line)
	}
	if len(got) != len(want) {
		t.Fatalf("got %q, want %q", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("line %d = %q, want %q (got all %q)", i+1, got[i], want[i], got)
		}
	}
}

